const diceSample64 = '';
let diceSample = null, diceMasterGain = null, diceSoundEpoch = 0, lastDiceStart = 0;
const diceVoices = new Set();
function stopDiceSounds() {
    diceSoundEpoch++;
    lastDiceStart = 0;
    for (const voice of diceVoices) {
        try {
            voice.stop();
        }
        catch {
        }
    }
    diceVoices.clear();
}

function diceSound() {
    if (!state.volume)
        return;
    const epoch = diceSoundEpoch;
    try {
        const ac = diceAudioCtx ??= new (window.AudioContext || window.webkitAudioContext)();
        if (!diceMasterGain) {
            const compressor = ac.createDynamicsCompressor();
            compressor.threshold.value = -12;
            compressor.knee.value = 15;
            compressor.ratio.value = 5;
            compressor.attack.value = .003;
            compressor.release.value = .18;
            diceMasterGain = ac.createGain();
            compressor.connect(diceMasterGain).connect(ac.destination);
            diceMasterGain.compressor = compressor;
        }
        diceMasterGain.gain.value = clamp(state.volume / 100, 0, 1);
        const resumed = ac.resume();
        if (!diceSample) {
            const data = Uint8Array.from(atob(diceSample64), x => x.charCodeAt(0));
            diceSample = ac.decodeAudioData(data.buffer).catch(e => {
                diceSample = null;
                throw e;
            });
        }
        Promise.all([resumed, diceSample]).then(([, buffer]) => {
            if (epoch !== diceSoundEpoch || !$('diceDialog').open || !state.volume)
                return;
            const voice = ac.createBufferSource();
            voice.buffer = buffer;
            voice.playbackRate.value = .97 + Math.random() * .06;
            voice.connect(diceMasterGain.compressor);
            diceVoices.add(voice);
            voice.onended = () => diceVoices.delete(voice);
            const start = Math.max(ac.currentTime + .21, lastDiceStart + .035);
            lastDiceStart = start;
            voice.start(start);
        }).catch(() => {
        });
    }
    catch {
    }
}

